import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    if n <= 1:
        return edge_distance.copy()
    tour = np.asarray(local_opt_tour, dtype=int)
    mask = ~np.eye(n, dtype=bool)
    mean_dist = edge_distance[mask].mean() if n > 1 else 1.0
    if mean_dist <= 0:
        mean_dist = 1.0
    penalty = 0.1 * mean_dist

    edges = []
    seen = set()
    for i in range(n):
        u = tour[i]
        v = tour[(i + 1) % n]
        if u == v:
            continue
        e = (u, v) if u < v else (v, u)
        if e not in seen:
            seen.add(e)
            edges.append(e)

    if not edges:
        return edge_distance.copy()

    utilities = np.array([
        edge_distance[u, v] / (1.0 + edge_n_used[u, v])
        for u, v in edges
    ])
    avg_util = utilities.mean()

    for (u, v), util in zip(edges, utilities):
        if util >= avg_util:
            edge_n_used[u, v] += 1
            edge_n_used[v, u] += 1

    updated_edge_distance = edge_distance + penalty * edge_n_used
    return updated_edge_distance

import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                         edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    if n == 0:
        return edge_distance.copy()
    tour = np.asarray(local_opt_tour, dtype=int).ravel()
    if tour.size != n:
        return edge_distance.copy()

    edges = []
    for k in range(n):
        i = int(tour[k])
        j = int(tour[(k + 1) % n])
        if i != j:
            edges.append((i, j))
    if not edges:
        return edge_distance.copy()

    utils = []
    for i, j in edges:
        d = float(edge_distance[i, j])
        p = float(edge_n_used[i, j])
        u = d / (1.0 + p) if d > 0 else 0.0
        utils.append((u, i, j))
    utils.sort(key=lambda x: x[0], reverse=True)

    if n > 1:
        triu = np.triu_indices(n, 1)
        mean_d = float(np.mean(edge_distance[triu]))
    else:
        mean_d = 1.0
    if mean_d <= 0:
        mean_d = 1.0
    lambda_pen = 0.15 * mean_d

    k = max(1, int(np.ceil(len(utils) / 3.0)))
    for idx in range(k):
        _, i, j = utils[idx]
        edge_n_used[i, j] += 1
        edge_n_used[j, i] += 1

    updated = edge_distance + lambda_pen * edge_n_used
    return updated

import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                         edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    tour_edges = set()
    for i in range(n):
        u = int(local_opt_tour[i])
        v = int(local_opt_tour[(i + 1) % n])
        if u != v:
            if u > v:
                u, v = v, u
            tour_edges.add((u, v))

    tour_edges = list(tour_edges)
    if not tour_edges:
        return edge_distance.copy()

    utils = [edge_distance[u, v] / (1.0 + edge_n_used[u, v]) for u, v in tour_edges]

    pos = edge_distance[edge_distance > 0]
    lam = 0.1 * np.median(pos) if pos.size > 0 else 1.0
    if lam <= 0:
        lam = 1.0

    med = np.median(utils)
    for (u, v), util in zip(tour_edges, utils):
        if util >= med:
            edge_n_used[u, v] += 1
            edge_n_used[v, u] += 1

    return edge_distance + lam * edge_n_used

import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    d = edge_distance
    n = d.shape[0]
    if n <= 1:
        return d.copy()

    tour = np.asarray(local_opt_tour, dtype=int).ravel()
    m = tour.size
    if m < 2:
        return d.copy()

    edges = set()
    for i in range(m):
        u = int(tour[i])
        v = int(tour[(i + 1) % m])
        if u == v:
            continue
        if u > v:
            u, v = v, u
        edges.add((u, v))

    if not edges:
        return d.copy()

    edges = list(edges)
    utils = np.empty(len(edges), dtype=float)
    for i, (u, v) in enumerate(edges):
        utils[i] = d[u, v] / (1.0 + edge_n_used[u, v])

    k = max(1, int(np.ceil(0.25 * len(edges))))
    if np.max(utils) <= 0:
        selected = range(len(edges))
    else:
        selected = np.argsort(-utils)[:k]

    pos = d[d > 0]
    avg = float(np.mean(pos)) if pos.size else 1.0
    lam = 0.2 * avg / max(1.0, np.sqrt(n))

    for idx in selected:
        u, v = edges[idx]
        edge_n_used[u, v] += 1
        edge_n_used[v, u] += 1

    updated = d + lam * edge_n_used
    np.fill_diagonal(updated, 0.0)
    return updated
